-- ═══ history-age-of-discovery — 大航海時代の光と影
insert into public.timelines (slug, owner_id, title, description, category, language, visibility, share_id, start_year, end_year, cover_seed)
values ('history-age-of-discovery', '00000000-0000-4000-8000-b596178c3ba4', '大航海時代の光と影', 'セウタ攻略から東インド会社まで約200年。航海・交易・征服の3層を重ね、世界が一つの経済圏に結ばれていく過程と、その裏で進んだ収奪と人口崩壊を同じ画面で見る年表。', 'history-politics', 'ja', 'public', 's_history-age-of-discovery', 1415, 1602, 'history-age-of-discovery')
on conflict (slug) do update set owner_id = excluded.owner_id, title = excluded.title, description = excluded.description, category = excluded.category,
  start_year = excluded.start_year, end_year = excluded.end_year, updated_at = now();
delete from public.layers where timeline_id = (select id from public.timelines where slug = 'history-age-of-discovery');
delete from public.events where timeline_id = (select id from public.timelines where slug = 'history-age-of-discovery');
insert into public.layers (timeline_id, name, color, position) values ((select id from public.timelines where slug = 'history-age-of-discovery'), '航海と探検', 'blue', 0);
insert into public.layers (timeline_id, name, color, position) values ((select id from public.timelines where slug = 'history-age-of-discovery'), '交易と経済', 'gold', 1);
insert into public.layers (timeline_id, name, color, position) values ((select id from public.timelines where slug = 'history-age-of-discovery'), '征服と先住民', 'pink', 2);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-age-of-discovery'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-age-of-discovery') and name = '航海と探検'),
          '1415-08-21', null, 'day', 'point', 'ポルトガルが北アフリカのセウタを攻略', 'ジョアン1世率いるポルトガル軍が、ジブラルタル海峡対岸の交易都市セウタを一日で攻略した。エンリケ航海王子も従軍したこの遠征は、大航海時代の出発点と位置づけられることが多い。

十字軍的な信仰の動機と、金と穀物の集まる北アフリカ交易への参入という経済の動機が重なっており、以後エンリケの支援でアフリカ西岸の組織的探検が始まる。信仰・栄光・利益が最初から不可分だったことを示す開幕である。', null,
          'verified', null, 'user', 0) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: Conquest of Ceuta', 'https://en.wikipedia.org/wiki/Conquest_of_Ceuta')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-age-of-discovery'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-age-of-discovery') and name = '航海と探検'),
          '1434-01-01', null, 'year', 'point', 'ジル・エアネスがボジャドール岬を越える', 'エンリケ航海王子の船長ジル・エアネスが、船乗りたちに「越えれば戻れない」と恐れられた西サハラ沖のボジャドール岬を初めて越えて帰還した。十数回の失敗の末の突破だったと伝えられる。

心理的な限界線の突破により、アフリカ西岸の南下が一気に進む。一方でこの南下は、10年後のラゴスでの奴隷競売(征服と先住民レイヤー)に直結しており、探検の一歩一歩が収奪の一歩でもあったという本年表の主題がここから始まる。', null,
          'verified', null, 'user', 1) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: Gil Eanes', 'https://en.wikipedia.org/wiki/Gil_Eanes')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-age-of-discovery'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-age-of-discovery') and name = '征服と先住民'),
          '1444-08-01', null, 'month', 'point', 'ラゴスでアフリカ人捕虜の大規模な競売', 'ポルトガル南部の港ラゴスで、西アフリカから連行された200人以上の捕虜が競売にかけられた。年代記作者ズララは、家族が引き離される光景への同情を記しつつ、事業自体は神意として正当化している。

**大西洋奴隷貿易の原型**となった出来事であり、以後アフリカ人の労働力は航海事業の収益源に組み込まれていく。喜望峰到達もアメリカ到達もまだ先のこの時点で、既に人身の売買が探検の経済を支え始めていた。', null,
          'unverified', '235人という人数や競売の詳細はズララ『ギニア発見征服誌』のほぼ単一の記録に依拠しており、第三者史料による検証はできない。', 'user', 2) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('ズララ『ギニア発見征服誌』(1450年代成立)', null)) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-age-of-discovery'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-age-of-discovery') and name = '航海と探検'),
          '1488-02-01', null, 'month', 'point', 'バルトロメウ・ディアスが喜望峰を回航', 'ポルトガルのバルトロメウ・ディアスが嵐に流されながらアフリカ大陸南端を回り込み、大陸の南に海が開けていることを確認した。帰路に望見した岬は、のちに「喜望峰」と名づけられる。

70年余りに及んだアフリカ西岸南下の到達点であり、インドへの海路が実在するという確信をポルトガルに与えた。この情報の蓄積が10年後のガマのインド航路開拓を可能にし、香辛料交易(交易と経済レイヤー)の構造を一変させる前提となった。', null,
          'verified', null, 'user', 3) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: Bartolomeu Dias', 'https://en.wikipedia.org/wiki/Bartolomeu_Dias')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-age-of-discovery'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-age-of-discovery') and name = '航海と探検'),
          '1492-10-12', null, 'day', 'point', 'コロンブス、カリブ海の島に到達', 'スペイン両王の支援を得たコロンブスが、大西洋を西へ約1か月航海してバハマ諸島の島に到達し、サンサルバドルと名づけた。彼は死ぬまでそこをアジアの一部と信じていた。

**「発見」は一方の側から見た言葉**であり、島には数万年来の先住民の歴史があった。この上陸を境に旧大陸と新大陸の生態系・病原体・人間が交わる「コロンブス交換」が始まり、以後の年表の光と影のすべてがこの日から分岐する。', null,
          'verified', null, 'user', 4) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: Voyages of Christopher Columbus', 'https://en.wikipedia.org/wiki/Voyages_of_Christopher_Columbus')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-age-of-discovery'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-age-of-discovery') and name = '征服と先住民'),
          '1493-01-01', '1600-01-01', 'year', 'period', 'アメリカ大陸先住民の人口激減', '接触開始からの約1世紀で、南北アメリカの先住民人口は天然痘・麻疹などの旧大陸由来の疫病、戦争、強制労働により激減した。地域によっては9割前後が失われたとする推計もある。

免疫のない集団を襲った疫病が最大の要因とされるが、征服と収奪が社会の回復力を奪ったことと不可分である。**大陸規模の人口崩壊**は労働力不足を生み、それを埋める形でアフリカ人奴隷貿易が拡大するという、影が影を呼ぶ連鎖の中心にこの期間がある。', null,
          'disputed', '接触前の人口推計自体が800万人台から1億人超まで研究者間で桁違いに分かれており、減少率・死者数は確定できない。', 'user', 5) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: Population history of Indigenous peoples of the Americas', 'https://en.wikipedia.org/wiki/Population_history_of_Indigenous_peoples_of_the_Americas')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-age-of-discovery'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-age-of-discovery') and name = '交易と経済'),
          '1494-06-07', null, 'day', 'point', 'トルデシリャス条約、世界を二分する線を引く', 'スペインとポルトガルが、ヴェルデ岬諸島西方の子午線を境に、新たに到達する土地の権利を二分する条約を結んだ。教皇の裁定を修正する形での、ヨーロッパ2国間の取り決めである。

当事者不在のまま**地図上の一本の線で世界の所有を宣言した**この条約は、大航海時代の発想を最も端的に示す。境界線の東側にあたったブラジルは後にポルトガル領となり、条約の線は現在の南米の言語地図にまで痕跡を残している。', null,
          'verified', null, 'user', 6) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: Treaty of Tordesillas', 'https://en.wikipedia.org/wiki/Treaty_of_Tordesillas')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-age-of-discovery'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-age-of-discovery') and name = '航海と探検'),
          '1498-05-20', null, 'day', 'point', 'ヴァスコ・ダ・ガマがインドのカリカットに到達', '喜望峰回りでインド洋を横断したガマの艦隊が、香辛料交易の中心カリカットに到達した。欧州からアジアへ直接至る海路が初めて実証された瞬間である。

ただしインド洋には既にアラブ・インド商人の成熟した交易網があり、ポルトガルは新参者にすぎなかった。持参した贈り物は現地の支配者に貧弱と一笑されている。以後ポルトガルは交渉ではなく艦砲による拠点支配へ転じ、航海の成果が武力交易(交易と経済レイヤー)へ姿を変えていく。', null,
          'verified', null, 'user', 7) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: Vasco da Gama', 'https://en.wikipedia.org/wiki/Vasco_da_Gama')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-age-of-discovery'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-age-of-discovery') and name = '航海と探検'),
          '1500-04-22', null, 'day', 'point', 'カブラルの艦隊がブラジルに到達', 'インドへ向かうため大西洋を大きく西へ迂回したカブラルの艦隊が、現在のブラジル沿岸に到達し、ポルトガル領有を宣言した。意図的な探査か偶然の漂着かは今も議論がある。

トルデシリャス条約(交易と経済レイヤー)の線の東側だったため、南米にポルトガル語圏が生まれる起点となった。当初は染料木の採取地にすぎなかったが、後に砂糖プランテーションとアフリカ人奴隷労働の中心地となり、条約の線が数百万人の運命を規定することになる。', null,
          'verified', null, 'user', 8) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: Pedro Álvares Cabral', 'https://en.wikipedia.org/wiki/Pedro_%C3%81lvares_Cabral')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-age-of-discovery'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-age-of-discovery') and name = '航海と探検'),
          '1519-09-20', '1522-09-06', 'day', 'period', 'マゼラン艦隊の世界周航', 'マゼラン率いる5隻・約270人の艦隊がスペインを出港し、南米南端の海峡を抜けて太平洋を横断した。マゼラン自身はフィリピンのマクタン島で戦死し、エルカーノ指揮下のビクトリア号1隻・生存者18人が3年後に帰港して史上初の世界周航が完成する。

地球が一続きの海で結ばれていることを実証し、地球の大きさを体感として示した航海である。同じ頃メキシコではコルテスの征服(征服と先住民レイヤー)が進行しており、探検の達成と征服の暴力が同時代であったことを両レイヤーの並置が示す。', null,
          'verified', null, 'user', 9) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: Magellan expedition', 'https://en.wikipedia.org/wiki/Magellan_expedition')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-age-of-discovery'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-age-of-discovery') and name = '征服と先住民'),
          '1521-08-13', null, 'day', 'point', 'テノチティトラン陥落、アステカ王国滅亡', 'コルテス率いるスペイン軍と先住民同盟軍が、湖上の大都市テノチティトランを長期の包囲戦の末に陥落させ、アステカ王国は滅亡した。包囲中の市内では天然痘が猛威を振るっていた。

数百人のスペイン人だけの勝利ではなく、アステカ支配に反発する先住民諸都市の大軍と、旧大陸由来の疫病という「見えない同盟者」が決定的だった。人口数十万を擁したとされる都市の廃墟の上にメキシコシティが築かれ、征服の統治が始まる。', null,
          'verified', null, 'user', 10) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: Fall of Tenochtitlan', 'https://en.wikipedia.org/wiki/Fall_of_Tenochtitlan')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-age-of-discovery'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-age-of-discovery') and name = '征服と先住民'),
          '1533-01-01', null, 'year', 'point', 'ピサロがインカ皇帝アタワルパを処刑', 'カハマルカで捕らえられていたインカ皇帝アタワルパが、部屋を満たす金銀の身代金を納めた後にもかかわらず、スペイン人により処刑された。ピサロの部隊は200人足らずでインカ帝国の中枢を制圧した。

内戦と疫病で弱っていた帝国の混乱に乗じた征服であり、身代金の金銀はスペインへ流れて欧州の貨幣経済を刺激した(交易と経済レイヤー)。約束と処刑の顛末は、征服の論理の身勝手さを示す事例として同時代から批判の対象となった。', null,
          'disputed', '処刑は1533年7月26日とされることが多いが、史料により日付・月に食い違いがあり確定していない。', 'user', 11) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: Atahualpa', 'https://en.wikipedia.org/wiki/Atahualpa')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-age-of-discovery'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-age-of-discovery') and name = '交易と経済'),
          '1543-01-01', null, 'year', 'point', '種子島に鉄砲が伝来', '中国船に乗って種子島に漂着したポルトガル人が火縄銃をもたらしたと『鉄炮記』は伝える。領主種子島時堯が2挺を購入し、国産化と改良が急速に進んで、戦国日本の戦争の形を変えた。

大航海時代の交易網が東アジアの島国にまで届いたことを示す出来事で、直後のザビエル来日(1549年)とあわせ、日本は銀の輸出国として世界経済(交易と経済レイヤーの主題)に組み込まれていく。ポトシとならび石見銀山の銀が世界を巡る時代の入口である。', null,
          'disputed', '1543年は『鉄炮記』(1606年成立)に基づく通説だが、ポルトガル側史料から1542年とする説もあり、伝来の年次・経緯には諸説ある。', 'user', 12) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: 鉄砲伝来', 'https://ja.wikipedia.org/wiki/鉄砲伝来')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-age-of-discovery'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-age-of-discovery') and name = '交易と経済'),
          '1545-01-01', null, 'year', 'point', 'ポトシ銀山の採掘が始まる', 'アンデス高地(現ボリビア)の標高4000メートルを超えるセロ・リコで銀鉱脈が確認され、採掘が始まった。ポトシは16世紀末には欧州の大都市に匹敵する人口を抱え、世界の銀生産の中心となる。

この銀はスペインを経由して欧州の物価革命を引き起こし、マニラ経由で中国にも流れて、**銀が初めて世界を一つの経済圏に結んだ**。その裏で先住民はミタ制と呼ばれる強制労働に動員され、過酷な坑内労働と水銀中毒が多数の命を奪い続けた。', null,
