-- ═══ history-democracy — 民主主義の系譜
insert into public.timelines (slug, owner_id, title, description, category, language, visibility, share_id, start_year, end_year, cover_seed)
values ('history-democracy', '00000000-0000-4000-8000-994488f0f29f', '民主主義の系譜', 'アテナイの民会からマグナ・カルタ、革命と人権宣言、普通選挙、そして20世紀の民主化の波まで。制度・思想・参政権の3つの層を重ねながら、「だれが決めるのか」という問いがどう受け継がれてきたのかを、授業のようにゆっくりたどっていきます。', 'history-politics', 'ja', 'public', 's_history-democracy', -508, 1994, 'history-democracy')
