insert into public.timelines (slug, owner_id, title, description, category, language, visibility, share_id, start_year, end_year, cover_seed)
values ('history-german-reunification', '00000000-0000-4000-8000-0c3d63d6338e', '東西ドイツ統一', '敗戦国の分割占領から1990年10月3日の統一まで。大国の外交、東ドイツの体制と経済、市民の動きを三層で重ね、45年の分断が1年足らずで解けた理由と、その後に残った課題を追う。', 'history-politics', 'ja', 'public', 's_history-german-reunification', 1945, 1994, 'history-german-reunification')
