          '1948-06-24', '1949-05-12', 'day', 'period', 'ベルリン封鎖と大空輸', '1948年6月24日、西側地区の通貨改革に反発したソ連は、西ベルリンへ通じる陸路と水路を全面封鎖した。米英は約11か月間、200万人の市民の食料と石炭を空輸で運び続け、1949年5月12日に封鎖は解除された。

冷戦最初の本格的な対決は、軍事衝突なしに西側の西ベルリン残留を確定させた。封鎖は西ベルリン市民の帰属意識を西側へ決定的に傾け、翌月からの二つの国家の建国(体制と経済レイヤー)への流れを不可逆にした。', null,
          'verified', null, 'user', 1) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: ベルリン封鎖', 'https://ja.wikipedia.org/wiki/ベルリン封鎖')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
