-- ═══ history-middle-east — 中東紛争の構造
insert into public.timelines (slug, owner_id, title, description, category, language, visibility, share_id, start_year, end_year, cover_seed)
values ('history-middle-east', '00000000-0000-4000-8000-c2f88a917d52', '中東紛争の構造', '百年にわたる中東の紛争を、戦争・外交・大国の介入という3つの層で重ねて歩きます。個々の衝突ではなく、同じ土地の上で紛争が繰り返される構造そのものを、地図を片手に浮かび上がらせる年表です。', 'history-politics', 'ja', 'public', 's_history-middle-east', 1917, 2024, 'history-middle-east')
