insert into public.timelines (slug, owner_id, title, description, category, language, visibility, share_id, start_year, end_year, cover_seed)
values ('history-silk-road', '00000000-0000-4000-8000-c2f88a917d52', 'シルクロードの2000年', 'ローマの絹熱から一帯一路まで、約2000年の道のりを歩きます。交易・帝国・宗教文化の3層を重ね、モノと信仰と権力が同じ道を分かち合い、道の盛衰が帝国の盛衰と重なるさまを、地図をたどるように眺める年表です。', 'history-politics', 'ja', 'public', 's_history-silk-road', 16, 2014, 'history-silk-road')
